; ==================================================================
; SPRITE INITIALIZATION FUNCTIONS
; ==================================================================

INIT_SPRITES:
    ; Initialize sprite system
    CALL CLEAR_ALL_SPRITES

    ; Load sprite patterns to VRAM
    CALL LOAD_SPRITE_PATTERNS

    ; Initialize sprite positions (all invisible by default)
    XOR A
    LD (active_sprite_count), A

    RET

LOAD_SPRITE_PATTERNS:
    ; Load all sprite patterns to VRAM sprite pattern table

    ; Load sprite 0: hero1
    LD HL, SPRITE_0_PATTERN
    LD DE, SPRPAT + (0 * 8)  ; Each sprite pattern is 8 bytes
    LD BC, 8
    CALL LDIRVM

    ; Load sprite 1: bird1
    LD HL, SPRITE_1_PATTERN
    LD DE, SPRPAT + (1 * 8)  ; Each sprite pattern is 8 bytes
    LD BC, 8
    CALL LDIRVM

    ; Load sprite 2: ball1
    LD HL, SPRITE_2_PATTERN
    LD DE, SPRPAT + (2 * 8)  ; Each sprite pattern is 8 bytes
    LD BC, 8
    CALL LDIRVM

    ; Load sprite 3: bird2
    LD HL, SPRITE_3_PATTERN
    LD DE, SPRPAT + (3 * 8)  ; Each sprite pattern is 8 bytes
    LD BC, 8
    CALL LDIRVM

    ; Load sprite 4: minipotato
    LD HL, SPRITE_4_PATTERN
    LD DE, SPRPAT + (4 * 8)  ; Each sprite pattern is 8 bytes
    LD BC, 8
    CALL LDIRVM

    ; Load sprite 5: blackDuck
    LD HL, SPRITE_5_PATTERN
    LD DE, SPRPAT + (5 * 8)  ; Each sprite pattern is 8 bytes
    LD BC, 8
    CALL LDIRVM
    RET

; ==================================================================
; SPRITE MANAGEMENT FUNCTIONS
; ==================================================================

; Show sprite (A = sprite number, B = X, C = Y, D = pattern, E = color)
SHOW_SPRITE:
    PUSH AF

    ; Set X position
    LD HL, sprite_x_pos
    LD A, E                       ; E was sprite number (from stack)
    LD E, A
    LD D, 0
    ADD HL, DE
    LD (HL), B                    ; Set X position

    ; Set Y position
    LD HL, sprite_y_pos
    LD E, A
    LD D, 0
    ADD HL, DE
    LD (HL), C                    ; Set Y position

    ; Set pattern
    LD HL, sprite_pattern
    LD E, A
    LD D, 0
    ADD HL, DE
    LD (HL), D                    ; Set pattern number

    ; Set color
    LD HL, sprite_color
    LD E, A
    LD D, 0
    ADD HL, DE
    LD (HL), E                    ; Set color

    POP AF
    RET

; Clear all sprites (make them invisible)
CLEAR_ALL_SPRITES:
    LD HL, sprite_y_pos
    LD DE, sprite_y_pos+1
    LD BC, 31                     ; 32 sprites - 1
    LD (HL), SPRITE_INVISIBLE     ; Y=209 (invisible)
    LDIR
    RET

; Hide specific sprite (A = sprite number)
HIDE_SPRITE:
    LD HL, sprite_y_pos
    LD E, A
    LD D, 0
    ADD HL, DE                    ; HL points to sprite Y position
    LD (HL), SPRITE_INVISIBLE     ; Make invisible
    RET

; Update sprite positions to VRAM
UPDATE_SPRITES_TO_VRAM:
    ; Copy sprite attributes from RAM to VRAM
    LD HL, sprite_y_pos
    LD DE, SPRATR
    LD BC, 128                    ; 32 sprites * 4 bytes each
    CALL LDIRVM
    RET

; ==================================================================
